-- Referentiel initial : secteurs, metiers, competences (catalogue unique, lien M:N metier-competence).
-- Reprise de l'ancien projet. Les descriptions "Competence de demonstration" ont ete retirees (NULL).
-- Methodes de validation par defaut : DOCUMENT, EVALUATION_CENTRE, PORTFOLIO, MAITRE_ARTISAN pour toutes
-- les competences. TEST_NUMERIQUE est ajoutee en V4 uniquement pour les competences qui ont un test.







SELECT c.id, m.id, TRUE
FROM competence c
JOIN methode_validation m ON m.code IN ('DOCUMENT','EVALUATION_CENTRE','PORTFOLIO','MAITRE_ARTISAN');
